void markTomorrow (Widget date) {
   char *tomorrowsDate = "04/20/93";
   XtVaSetValues (date, XmNvalue, tomorrowsDate, NULL);
} // markTomorrow

void markYesterday (Widget date) {
   char *yesterdaysDate = "04/18/93";
